-- Source SHA256: FEAD23B6FE89398FE2A9DC4BD49C971305A6AD865AD5E8C6CB42DA4DDD235AC6
-- Local replay required before any staging promotion.
-- OTOTR FRANCHISE CONTRACT UPDATE RPC CANDIDATE
create or replace function finance_private.current_franchise_contract_update_committer_is_trusted() returns boolean language sql stable security definer set search_path='' as $$select false$$;
create or replace function finance_private.resolve_franchise_contract_update_scope(p_actor_id uuid,p_contract_id uuid,p_permission text) returns jsonb language sql stable security definer set search_path='' as $$select null::jsonb$$;
create or replace function finance_api.authorize_franchise_contract_update(p_contract_id uuid,p_permission text) returns jsonb language sql stable security definer set search_path='' as $$select case when auth.uid() is null or p_permission<>'finance.contracts.update' then null::jsonb else finance_private.resolve_franchise_contract_update_scope(auth.uid(),p_contract_id,p_permission) end$$;
create or replace function finance_api.commit_franchise_contract_update(p_actor_id uuid,p_legal_entity_id uuid,p_dealer_legal_entity_id uuid,p_dealer_account_id uuid,p_branch_id uuid,p_contract_id uuid,p_contract_code text,p_reference_hash text,p_document_ids uuid[],p_expected_version bigint,p_idempotency_key text,p_intent_hash text,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,finance,finance_private as $$
declare c finance.franchise_contracts%rowtype;v_existing record;v_docs integer;v_new bigint;v_purpose text;v_payload jsonb;v_previous text;v_audit text;
begin
 if not finance_private.current_franchise_contract_update_committer_is_trusted() then raise exception using errcode='42501',message='trusted franchise contract update committer required';end if;
 if p_expected_version<1 or p_document_ids is null or pg_catalog.length(pg_catalog.btrim(coalesce(p_contract_code,''))) not between 1 and 200 or p_reference_hash!~'^[a-fA-F0-9]{64}$' or pg_catalog.length(pg_catalog.btrim(coalesce(p_idempotency_key,''))) not between 8 and 200 or p_intent_hash!~'^[a-fA-F0-9]{64}$' then raise exception using errcode='22023',message='invalid franchise contract update command';end if;
 select * into c from finance.franchise_contracts where id=p_contract_id for update;if not found then raise exception using errcode='P0002',message='contract not found';end if;
 select om.payload into v_existing from finance.outbox_messages om where om.legal_entity_id=c.legal_entity_id and om.event_type='FRANCHISE_CONTRACT_DRAFT_UPDATED' and om.aggregate_id=c.id and om.payload->>'idempotencyKey'=p_idempotency_key order by om.created_at_utc desc,om.id desc limit 1;if found then if v_existing.payload->>'intentHash'=p_intent_hash then return pg_catalog.jsonb_build_object('outcome','REPLAY','contractId',c.id,'dealerLegalEntityId',c.dealer_legal_entity_id,'contractCode',v_existing.payload->>'contractCode','status','DRAFT','draftVersionId',null,'activeVersionId',null,'version',(v_existing.payload->>'version')::bigint);end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if c.legal_entity_id<>p_legal_entity_id or c.dealer_legal_entity_id<>p_dealer_legal_entity_id or c.status<>'DRAFT' or c.version<>p_expected_version then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 if not exists(select 1 from finance.dealer_accounts da join finance.branches b on b.legal_entity_id=da.legal_entity_id and b.dealer_legal_entity_id=da.dealer_legal_entity_id where da.id=p_dealer_account_id and da.legal_entity_id=p_legal_entity_id and da.dealer_legal_entity_id=p_dealer_legal_entity_id and b.id=p_branch_id) then raise exception using errcode='42501',message='contract update three dimensional scope denied';end if;
 if exists(select 1 from finance.franchise_contracts x where x.legal_entity_id=p_legal_entity_id and x.contract_code=p_contract_code and x.id<>c.id) then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;
 select pg_catalog.count(distinct dr.external_document_id) into v_docs from finance.document_references dr where dr.legal_entity_id=p_legal_entity_id and dr.status='ACTIVE' and dr.external_document_id=any(coalesce(p_document_ids,array[]::uuid[]));if v_docs<>pg_catalog.cardinality(p_document_ids) then raise exception using errcode='23514',message='all contract documents must be active';end if;
 v_new:=c.version+1;v_purpose:='CONTRACT_EVIDENCE_V'||v_new::text;update finance.franchise_contracts set contract_code=p_contract_code,version=v_new,correlation_id=p_correlation_id where id=c.id;
 insert into finance.document_links(legal_entity_id,document_reference_id,subject_type,subject_id,purpose_code,created_by,correlation_id) select p_legal_entity_id,dr.id,'FRANCHISE_CONTRACT',c.id,v_purpose,p_actor_id,p_correlation_id from finance.document_references dr where dr.legal_entity_id=p_legal_entity_id and dr.status='ACTIVE' and dr.external_document_id=any(coalesce(p_document_ids,array[]::uuid[]));
 v_payload:=pg_catalog.jsonb_build_object('contractId',c.id,'dealerLegalEntityId',c.dealer_legal_entity_id,'branchId',p_branch_id,'contractCode',p_contract_code,'referenceHash',p_reference_hash,'evidencePurpose',v_purpose,'documentCount',v_docs,'version',v_new,'idempotencyKey',p_idempotency_key,'intentHash',p_intent_hash);
 insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(p_legal_entity_id,'finance.contract','FRANCHISE_CONTRACT_DRAFT_UPDATED','FRANCHISE_CONTRACT',c.id,v_new,v_payload,p_intent_hash,'PENDING',p_correlation_id);
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||p_legal_entity_id::text,0));select integrity_hash into v_previous from finance.audit_events where legal_entity_id=p_legal_entity_id order by created_at_utc desc,id desc limit 1;v_audit:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(v_previous,'GENESIS')||':'||c.id::text||':FRANCHISE_CONTRACT_DRAFT_UPDATED:'||p_intent_hash||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(p_legal_entity_id,p_actor_id,'USER','FRANCHISE_CONTRACT_DRAFT_UPDATED','FRANCHISE_CONTRACT',c.id,'ALLOW',p_intent_hash,v_previous,v_audit,pg_catalog.jsonb_build_object('branchId',p_branch_id,'referenceHash',p_reference_hash,'evidencePurpose',v_purpose,'documentCount',v_docs,'previousVersion',c.version),p_correlation_id);
 return pg_catalog.jsonb_build_object('outcome','UPDATED','contractId',c.id,'dealerLegalEntityId',c.dealer_legal_entity_id,'contractCode',p_contract_code,'status','DRAFT','draftVersionId',null,'activeVersionId',null,'version',v_new);
end$$;
revoke all on function finance_private.current_franchise_contract_update_committer_is_trusted() from public,anon,authenticated;revoke all on function finance_private.resolve_franchise_contract_update_scope(uuid,uuid,text) from public,anon,authenticated;revoke all on function finance_api.authorize_franchise_contract_update(uuid,text) from public,anon;grant execute on function finance_api.authorize_franchise_contract_update(uuid,text) to authenticated;revoke all on function finance_api.commit_franchise_contract_update(uuid,uuid,uuid,uuid,uuid,uuid,text,text,uuid[],bigint,text,text,uuid) from public,anon,authenticated;
